#include <iostream>

int main() {
    int n;
    std::cin >> n;
    if (n <= 60) {
        unsigned long long ans = (1ULL << (n + 1)) - 2;
        std::cout << ans << std::endl;
    } else {
        // For n > 60, use string arithmetic (not required by constraints n <= 55)
        std::string s = "2";
        for (int i = 0; i < n + 1; ++i) {
            int carry = 0;
            for (int j = s.size() - 1; j >= 0; --j) {
                int d = (s[j] - '0') * 2 + carry;
                s[j] = '0' + (d % 10);
                carry = d / 10;
            }
            if (carry) s.insert(s.begin(), '0' + carry);
        }
        // subtract 2
        int i = s.size() - 1;
        int borrow = 2;
        while (borrow > 0 && i >= 0) {
            int d = (s[i] - '0') - borrow;
            if (d < 0) {
                d += 10;
                borrow = 1;
            } else {
                borrow = 0;
            }
            s[i] = '0' + d;
            --i;
        }
        // remove leading zeros
        size_t pos = s.find_first_not_of('0');
        if (pos != std::string::npos) s = s.substr(pos);
        else s = "0";
        std::cout << s << std::endl;
    }
    return 0;
}
